new:
pConst[c_, ell_, ass_] := (
  If[! PolynomialQ[c, ell], fail["UnsupportedCoefficient", "Logarithmic coefficients must be polynomials.", <|"Coefficient" -> c|>]];
  If[! And @@ (TrueQ[Refine[Element[#, Reals], ass, Assumptions -> True]] & /@ CoefficientList[c, ell]),
    fail["UnprovedRealCoefficient", "Every admitted coefficient must be real under the explicit assumptions.", <|"Coefficient" -> c|>]];
  If[zeroQ[c, ass], {{}, Infinity, 0}, {{{0, c}}, Infinity, 0}]);
